from pydantic import BaseModel, validator

class ThresholdUpdate(BaseModel):
    threshold: float
    unit: str = 'ppm'

    @validator('threshold')
    def validate_threshold(cls, v):
        if not (0 < v < 10000):
            raise ValueError('Threshold out of safe range')
        return v

    class Config:
        extra = 'forbid'  # رفض أي field زيادة!

@app.route('/api/alarm-threshold/<sensor_id>', methods=['PUT'])
def set_threshold(sensor_id):
    try:
        data = ThresholdUpdate(**request.json)  # forbid extra fields
    except ValidationError as e:
        abort(400, str(e))
    return update_threshold(sensor_id, data.threshold)
