## Security Headers Implementation — خطوة بخطوة

### Step 1: Nginx Configuration (الكامل)

```nginx
# /etc/nginx/sites-available/scada-dashboard

server {
    listen 443 ssl http2;
    server_name scada-dashboard.local;

    # SSL Configuration
    ssl_certificate     /etc/ssl/certs/scada-dashboard.pem;
    ssl_certificate_key /etc/ssl/private/scada-dashboard.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;

    # === الـ 5 Security Headers الأساسية ===

    # 1. Content-Security-Policy
    add_header Content-Security-Policy "
        default-src 'self';
        script-src 'self' 'nonce-$request_id';
        style-src 'self' 'unsafe-inline';
        img-src 'self' data:;
        font-src 'self';
        connect-src 'self' ws://scada-dashboard.local wss://scada-dashboard.local;
        frame-ancestors 'none';
        base-uri 'self';
        form-action 'self';
        object-src 'none';
    " always;

    # 2. X-Frame-Options (للـ browsers القديمة)
    add_header X-Frame-Options "DENY" always;

    # 3. X-Content-Type-Options
    add_header X-Content-Type-Options "nosniff" always;

    # 4. Strict-Transport-Security
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

    # 5. Referrer-Policy
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # === Headers إضافية مهمة ===

    # Disable XSS Auditor (آمن أكتر!)
    add_header X-XSS-Protection "0" always;

    # Permissions Policy
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;

    # Cache control للـ SCADA data
    add_header Cache-Control "no-store, no-cache, must-revalidate" always;

    # Proxy to Flask
    location / {
        proxy_pass http://127.0.0.1:5000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # WebSocket support
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

# HTTP → HTTPS redirect
server {
    listen 80;
    server_name scada-dashboard.local;
    return 301 https://$server_name$request_uri;
}
```

### Step 2: CSP Nonce Implementation في Flask

```python
from flask import Flask, make_response
import secrets

app = Flask(__name__)

@app.after_request
def add_csp_nonce(response):
    # Generate nonce لكل request
    nonce = secrets.token_urlsafe(16)
    response.headers['Content-Security-Policy'] = (
        f"default-src 'self'; "
        f"script-src 'self' 'nonce-{nonce}'; "
        f"style-src 'self' 'unsafe-inline'; "
        f"connect-src 'self' ws://scada-dashboard.local; "
        f"frame-ancestors 'none'; "
        f"form-action 'self'; "
        f"object-src 'none'"
    )
    # خزّن الـ nonce في g عشان الـ templates تستخدمه
    g.csp_nonce = nonce
    return response
```

